using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_api")]
    [Description("Fetches data from an external API endpoint and returns the response body.")]
    public static async Task<string> FetchApiAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiFetchTool> logger,
        [Description("The full URL to fetch (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching URL: {Url}", url);

        var client = httpClientFactory.CreateClient("ApiClient");

        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Url}", body.Length, url);
        return body;
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize")]
    [Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<ChatMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum number of sentences (default: 3)")] int? maxSentences = 3)
    {
        return
        [
            new ChatMessage(
                ChatMessageRole.User,
                $"""
                Summarize the following text in at most {maxSentences ?? 3} sentences.
                Be concise and capture the key points.

                Text:
                {text}
                """)
        ];
    }
}

